    w=I.build({'q_E2':1,'q_W1u':5,'t_green':a,'ok':-a*c},{'d_E2':1,'q_W1u':5,'t_green':a,'ok':-a*c})
    for ln in lanes:
        for pre in ('q_','d_'):
            j=ix[pre+ln]
            w['W1'][:,45]+=b/len(lanes)*W0['W1'][:,j]
            w['W1'][:,44]+=-b*cb/len(lanes)*W0['W1'][:,j]
    return w
def mk(p,t,**kw):
    x=np.zeros(46); x[40+p]=1; x[44]=1; x[45]=t
    for k,v in kw.items(): x[ix['q_'+k]]=v; x[ix['d_'+k]]=v
    return x
probes=[('empty',{}),('N0',dict(N0=.335)),('N1',dict(N1=.335)),('S0',dict(S0=.335)),('S1',dict(S1=.335)),('N2',dict(N2=.335)),('E1',dict(E1=.335)),('W1u.03',{})]
def table(w):
